INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-modelado-del-alfarero-scout', 'El Modelado del Alfarero Scout', 'Dinámica de confianza corporal y modelado kinésico donde los scouts moldean la figura de un compañero como si fuera arcilla viva.', '<h2>📜 Descripción de El Modelado del Alfarero Scout</h2>
<p><b>El Modelado del Alfarero Scout</b> es una dinámica de sensibilización corporal, trabajo en parejas y confianza mutua. Los participantes se organizan en duplas: uno de los scouts asume la posición de una ''bola de barro o arcilla blanda'' acurrucándose en el suelo o colchoneta, mientras su compañero asume el rol del ''Alfarero''. Con delicadeza y respeto, el alfarero ''amasa'' y coloca suavemente los brazos, piernas, cabeza y tronco del compañero en la postura de una estatua o figura artística de campamento. El scout que actúa como barro no se mueve por sí mismo, sino que conserva fielmente la postura en la que es posicionado hasta que la escultura es completada y admirada por la unidad.</p>
<p>Esta dinámica ejercita la soltura muscular, la contención afectiva y el respeto por el esquema corporal en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega El Modelado del Alfarero Scout?</h2>
<p>Para llevar a cabo la dinámica con solemnidad y cuidado, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Formación de Parejas:</b> Se dividen los beneficiarios en parejas del mismo rango etario o patrulla, ubicándose sobre una superficie limpia o césped.</li>
  <li><b>Preparación de la Arcilla:</b> El scout ''Barro'' se ovilla relajadamente en el suelo en estado de relajación total muscular.</li>
  <li><b>El Trabajo del Alfarero:</b> Al toque de silbato, el ''Alfarero'' amasa suavemente los hombros y extremidades del compañero y las moldea con cuidado hasta crear una figura con concepto (ej. <i>''El Explorador con Linterna''</i> o <i>''El Águila en Vuelo''</i>).</li>
  <li><b>Exposición de Esculturas:</b> Los alfareros caminan por la sala observando las distintas estatuas creadas por sus pares antes de invertir los roles.</li>
  <li><b>Intercambio de Roles:</b> Se invierten las funciones de Alfarero y Barro para que todos vivan la experiencia de contención y creación.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Modelado del Alfarero Scout</h2>
<p>La actividad valora el respeto corporal y la expresividad en el Tally:</p>
<ul>
  <li><b>Mayor Cuidado y Delicadeza:</b> Otorgar 5 puntos al Alfarero que modele con mayor suavidad y respeto las articulaciones del compañero.</li>
  <li><b>Expresividad de la Escultura:</b> Otorgar 3 puntos a la pareja cuya figura final transmita el mensaje o concepto más original.</li>
  <li><b>Confianza y Relajación:</b> Otorgar 3 puntos al scout que logre la mayor relajación tónica en su rol de arcilla.</li>
</ul>', '/uploads/el-modelado-del-alfarero-scout.webp', 'publicado', '{"areas": ["corporalidad", "sociabilidad", "afectividad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Ninguno"], "objetivos": ["Conocer las capacidades corporales", "Reforzar el conocimiento del cuerpo", "Desarrollar el carácter mediante la cooperación", "Fomentar un entorno de confianza"], "justificacion_areas": "El Modelado del Alfarero Scout potencia la corporalidad al afinar la percepción propioceptiva, la soltura articular y el conocimiento respetuoso de la anatomía. Desarrolla la sociabilidad al fomentar el trabajo armónico y la desinhibición social en parejas. Fortalece la afectividad al construir un clima de contención, cuidado mutuo y absoluta confianza interpersonal.", "variaciones": "<b>El Alfarero de Alambre:</b> El scout actúa como un hilo de alambre rígido ofreciendo una leve resistencia muscular al modelado del compañero.<br><b>El Escultor Ciego:</b> El alfarero realiza el modelado con los ojos vendados palpando únicamente las posiciones kinésicas.<br><b>Modelado de Patrulla:</b> Dos alfareros moldean en conjunto a una estatua compuesta por dos o tres beneficiarios.", "recomendaciones": "Generar un ambiente de seriedad y respeto absoluto por la corporalidad del compañero. Asegurar que las manipulaciones kinésicas sean siempre suaves y cuidadosas.", "objetivos_educativos": [{"id": "d9ebcd96-c9cf-444f-94fb-5569110a1b99", "area": "Corporalidad", "unidad": "Manada", "texto": "Participo en actividades que me ayudan a tener un cuerpo cada vez más fuerte, ágil, veloz y flexible.", "como_se_cumple": "Participando en el modelado kinésico para ganar flexibilidad y relajación articular."}, {"id": "626a313e-0407-4cfd-b714-c6aa6e51738c", "area": "Corporalidad", "unidad": "Manada", "texto": "Manejo cada vez mejor mis brazos, piernas, manos y pies.", "como_se_cumple": "Afinando el control de brazos y piernas al dejarse posicionar en figuras armónicas."}, {"id": "273f60b8-7953-4416-97c3-e8c83615364f", "area": "Corporalidad", "unidad": "Compañía", "texto": "Participo en actividades que me ayudan a mantener mi cuerpo fuerte y sano.", "como_se_cumple": "Ejercitando la soltura tónica y la conciencia corporal en el modelado artístico."}, {"id": "91473f71-9345-4bcf-bfc7-dea709d12361", "area": "Corporalidad", "unidad": "Compañía", "texto": "Respeto mi cuerpo y el de los demás.", "como_se_cumple": "Respetando la anatomía e integridad corporal de la compañera durante el modelado."}, {"id": "5c9843d1-39fd-4298-870c-5e46f29ffbf6", "area": "Corporalidad", "unidad": "Tropa", "texto": "Participo en actividades que me ayudan a mantener mi cuerpo fuerte y sano.", "como_se_cumple": "Perfeccionando la propiocepción y el tono muscular en la Tropa."}, {"id": "fb56310a-a9cf-46e3-9c34-c4643f6b9035", "area": "Corporalidad", "unidad": "Tropa", "texto": "Respeto mi cuerpo y el de los demás.", "como_se_cumple": "Fomentando el respeto y la delicadeza kinésica hacia el cuerpo de los pares."}, {"id": "ab6e594f-b0a0-4e6d-96aa-7779299b02ef", "area": "Afectividad", "unidad": "Manada", "texto": "Trato con cariño a los demás en la Manada y me gusta que me traten igual.", "como_se_cumple": "Tratando con cuidado y afecto sincero al compañero al posicionar sus extremidades."}, {"id": "c8993915-0234-464c-934e-2a09f8c4338e", "area": "Afectividad", "unidad": "Manada", "texto": "Digo lo que pienso sin ofender o insultar a mis compañeros ni burlarme de ellos.", "como_se_cumple": "Disfrutando de la experiencia artística sin realizar burlas sobre la figura creada."}, {"id": "2f8359db-221e-4a64-b2df-2b3e7b74a2db", "area": "Afectividad", "unidad": "Compañía", "texto": "Escucho las opiniones de las demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Sintonizando con el ritmo y nivel de comodidad de la compañera en la dinámica."}, {"id": "672a5da0-8cab-42bb-85dd-0d1f285a1b91", "area": "Afectividad", "unidad": "Compañía", "texto": "Digo lo que pienso con respeto hacia las demás personas.", "como_se_cumple": "Construyendo un ambiente de contención y absoluta confianza mutua."}, {"id": "a4060c60-7ce9-425b-bf2a-76941a689937", "area": "Afectividad", "unidad": "Tropa", "texto": "Escucho las opiniones de los demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Desarrollando sensibilidad táctil y empatía no verbal en el equipo."}, {"id": "4ade9c82-6b0d-4a44-8bc6-2eb47a011ffb", "area": "Afectividad", "unidad": "Tropa", "texto": "Digo lo que pienso con respeto hacia los demás personas.", "como_se_cumple": "Demostrando lealtad y apoyo afectivo maduro entre los integrantes de la patrulla."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

